import{z as o,x as s,o as l,c as m,q as B,j as r,D as A,d as a,s as n,S as i,b as e}from"./chunks/framework.C8m1ZpeB.js";const k=JSON.parse('{"title":"多模态 KV 管理","description":"","frontmatter":{"title":"多模态 KV 管理","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/mm-multimodal-kv.md","filePath":"llm/mm-multimodal-kv.md","lastUpdated":1791413859000}'),p={name:"llm/mm-multimodal-kv.md"};function d(D,E,C,V,K,f){const t=s("Mermaid");return l(),m("div",null,[E[2]||(E[2]=B('<h1 id="多模态-kv-管理" tabindex="-1">多模态 KV 管理 <a class="header-anchor" href="#多模态-kv-管理" aria-label="Permalink to &quot;多模态 KV 管理&quot;">​</a></h1><div class="epigraph"><p>文本会话的 KV 按千 token 计，多模态会话的 KV 按「几张图」计；前缀缓存的键与驱逐的秤都得重做。</p><footer>—— 据 Kwon et al., PagedAttention, SOSP 2023 与 vLLM 多模态前缀缓存实现整理</footer></div><p><a href="/llm/mm-speech-serving">上一课</a>把语音的四段延迟分了账；图、视频、语音进了 prefill 之后，共同下游都是 KV。分页、共享与驱逐的机制由 <a href="/llm/kv-map">KV 生命周期</a>一线讲过，本课不重推，只写多模态负载改了什么：视觉 token 的 KV 比文本大一到两个量级、复用结构完全不同、历史图像在多轮里如何存留成为独立的策略问题。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>尺寸失衡是根。每 token 的 KV 字节是固定的（层数 × 2 × KV 头数 × 头维 × 精度字节数），而一张文档页按<a href="/llm/mm-visual-token-budget">视觉 token 预算</a>轻松用掉一千五百 token——相当于把一整章文本的 KV 一次性塞进会话。后果有三：按「请求数 × 平均文本长度」估容量全部失效；同样并发水位下，图文负载的 KV 池比纯文本早得多进入驱逐区；多轮会话里，几轮之前的截图还整幅常驻，用户却再也不会问它。</p><p>复用结构也不同。文本前缀缓存的命中主体是系统提示与少样本段，小而极稳；图像 KV 的大头是内容块，大而集中——爆款图、同商品图、同文档页被反复请求，命中时收益巨大，不命中时占地巨大。高收益与高风险挂在同一个键上。</p><p><span class="marginnote">KV 缓存可以理解为「已读内容的笔记」：模型每读一个 token，就记下它的钥匙（K）和内容（V），之后生成新词时反复翻笔记，而不必重读原文。笔记人人都要记，所以图一多，先被塞爆的是笔记本，不是对话文本。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>缓存放两级。第一级是<a href="/llm/mm-serving-vision-encoder">嵌入缓存</a>：图像内容 hash 加预处理参数与编码器版本，命中则连编码器都不用跑。第二级是 <strong>KV 块缓存</strong>：把「图像嵌入 + 对话模板版本」映射到已算好的 KV 块，命中则跳过整段视觉 prefill。两级条件不同——嵌入命中不等于 KV 命中，模板或位置变了，嵌入还能用，KV 必须重算；反过来 KV 命中蕴含嵌入有效。命中链依次短路的是编码器、prefill 两段成本。</p><p>驱逐要用多模态自己的秤。块的处置按「字节 × 复用概率」排序：图像块单体大，驱逐一块回收的字节顶几十个文本块，所以<strong>先审大块</strong>；但点播集中度高的图命中率高，复用概率要用命中率数据喂，不能拍脑袋。会话内的存留策略独立于全局驱逐：翻篇的图像不走驱逐，走<strong>降采样重算</strong>——把历史大图换成低预算版本重 prefill，用一次小计算换长期的常驻占用，这是文本会话里不存在的第三条路（驱逐、保留之外）。</p><p><span class="marginnote">KV 字节账：28 层、4 个 KV 头、头维 128、bf16 时每 token 为 \\(28\\times2\\times4\\times128\\times2\\approx57\\) KB；一张 1536-token 的图约 87 MB，抵得上近两千 token 文本块的几十倍单体。图文并发容量必须按「图数」而不是「请求数」估。</span></p>',11)),(l(),r(i,null,{default:A(()=>[n(t,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20REQ%5B%22%E5%A4%9A%E6%A8%A1%E6%80%81%E8%AF%B7%E6%B1%82%22%5D%20--%3E%20L1%7B%22%E5%B5%8C%E5%85%A5%E7%BC%93%E5%AD%98%E5%91%BD%E4%B8%AD%3F%22%7D%0A%20%20L1%20--%3E%7C%E5%90%A6%7C%20ENC%5B%22%E7%BC%96%E7%A0%81%E5%99%A8%E7%AE%97%E5%B5%8C%E5%85%A5%22%5D%0A%20%20L1%20--%3E%7C%E6%98%AF%E6%88%96%E7%AE%97%E5%AE%8C%7C%20L2%7B%22KV%20%E5%9D%97%E7%BC%93%E5%AD%98%E5%91%BD%E4%B8%AD%3F%22%7D%0A%20%20L2%20--%3E%7C%E6%98%AF%7C%20REUSE%5B%22%E5%A4%8D%E7%94%A8%E8%A7%86%E8%A7%89%20KV%20%E5%9D%97%22%5D%0A%20%20L2%20--%3E%7C%E5%90%A6%7C%20PF%5B%22%E8%A7%86%E8%A7%89%E6%AE%B5%20prefill%20%E5%BB%BA%E5%9D%97%22%5D%0A%20%20ENC%20--%3E%20PF%0A%20%20REUSE%20--%3E%20SH%5B%22%E5%BC%95%E7%94%A8%E8%AE%A1%E6%95%B0%E5%85%B1%E4%BA%AB%22%5D%0A%20%20PF%20--%3E%20SH%0A%20%20SH%20--%3E%20EV%7B%22%E5%86%85%E5%AD%98%E5%8E%8B%E5%8A%9B%3F%22%7D%0A%20%20EV%20--%3E%7C%E6%98%AF%7C%20EJECT%5B%22%E6%8C%89%E5%AD%97%E8%8A%82%C3%97%E5%91%BD%E4%B8%AD%E7%8E%87%E9%A9%B1%E9%80%90%E5%A4%A7%E5%9D%97%22%5D%0A%20%20EV%20--%3E%7C%E5%90%A6%E6%88%96%E4%BC%9A%E8%AF%9D%E7%BF%BB%E7%AF%87%7C%20RES%5B%22%E5%8E%86%E5%8F%B2%E5%9B%BE%E9%99%8D%E9%87%87%E6%A0%B7%E9%87%8D%E7%AE%97%22%5D%0A"})]),fallback:A(()=>[...E[0]||(E[0]=[a(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=e("h2",{id:"机制",tabindex:"-1"},[a("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=e("p",null,[a("两级缓存的结构解释了为什么键必须分层。嵌入层键负责「编码结果是否仍为真」，由图像内容、预处理、编码器版本决定；KV 层键负责「这段 KV 是否能拼进当前上下文」，还要加上模板与位置布局。任何一层键少一项，失效就不传播——旧 KV 被新请求直接拼用，错误以「模型好像变笨」的形式出现，且只在部分请求上复现。"),e("span",{class:"marginnote"},"初学者容易以为「嵌入缓存命中了就万事大吉」——实际上嵌入只是原料，KV 是按当前对话的模板和位置把原料拼装好的半成品；对话模板一换，原料还能用，半成品整批报废。就像同一份食材，换个菜谱就得重做。"),a("这也是"),e("a",{href:"/llm/mm-serving-vision-encoder"},"缓存键版本纪律"),a("在 KV 层的加倍：模板升级、上下文重排、位置编码改动都要进键。")],-1)),(l(),r(i,null,{default:A(()=>[n(t,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20CH%7B%22%E5%93%AA%E4%B8%AA%E7%BB%84%E4%BB%B6%E5%8F%98%E4%BA%86%3F%22%7D%0A%20%20CH%20--%3E%7C%22%E7%BC%96%E7%A0%81%E5%99%A8%E6%88%96%E9%A2%84%E5%A4%84%E7%90%86%22%7C%20K1%5B%22%E5%B5%8C%E5%85%A5%E9%94%AE%E5%A4%B1%E6%95%88%22%5D%0A%20%20CH%20--%3E%7C%22%E5%AF%B9%E8%AF%9D%E6%A8%A1%E6%9D%BF%E6%88%96%E4%BD%8D%E7%BD%AE%E5%B8%83%E5%B1%80%22%7C%20K2%5B%22%E4%BB%85%20KV%20%E9%94%AE%E5%A4%B1%E6%95%88%22%5D%0A%20%20CH%20--%3E%7C%22%E9%83%BD%E6%B2%A1%E5%8F%98%22%7C%20K3%5B%22%E4%B8%A4%E7%BA%A7%E7%85%A7%E5%B8%B8%E5%91%BD%E4%B8%AD%22%5D%0A%20%20K1%20--%3E%20R1%5B%22%E9%87%8D%E8%B7%91%E7%BC%96%E7%A0%81%E5%99%A8%20%2B%20%E9%87%8D%E7%AE%97%E8%A7%86%E8%A7%89%20prefill%22%5D%0A%20%20K2%20--%3E%20R2%5B%22%E5%B5%8C%E5%85%A5%E7%85%A7%E7%94%A8%EF%BC%8C%E9%87%8D%E7%AE%97%E8%A7%86%E8%A7%89%20prefill%22%5D%0A%20%20K3%20--%3E%20R3%5B%22%E9%9B%B6%E9%87%8D%E7%AE%97%EF%BC%8C%E7%9B%B4%E6%8E%A5%E5%A4%8D%E7%94%A8%22%5D%0A%20%20R1%20--%3E%20W%5B%22%E6%BC%8F%E8%BF%9B%E9%94%AE%20%3D%20%E9%83%A8%E5%88%86%E8%AF%B7%E6%B1%82%E9%9D%99%E9%BB%98%E5%8F%98%E7%AC%A8%22%5D%0A%20%20R2%20--%3E%20W%0A"})]),fallback:A(()=>[...E[1]||(E[1]=[a(" Loading... ",-1)])]),_:1})),E[5]||(E[5]=B('<p>降采样重算的账要算两头。收益是常驻 KV 从全预算降到低预算版，会话能容纳的轮数与并发显著上升；成本是一次低分辨率 prefill，外加可复现性损失——历史里的图「变糊」之后，追问细节的答案可能与当初不同。所以降采样要留档：记录原预算与现预算，追问细节且原图仍在嵌入缓存时，透明地重算升回。</p><p><span class="marginnote">降采样重算类似把相册里的原图换成缩略图长期保存：平时翻相册毫无问题，想放大看细节时再回原库调原图——「留档」就是保证回原库这条路随时可走的关键一步，少了它历史图就永远糊了。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>KV 量化对视觉前缀不能沿用文本结论：视觉 token 冗余高，直觉上更耐压，但文档图表类高信息密度 token 与文字混在同一序列，敏感度要按模态分别评测（见 <a href="/llm/kv-quant-int8-int4">KV 量化</a>）。音频会话的 KV 时效短：通话结束，上下文价值归零，缓存 TTL 与图文不同，默认即弃。跨机迁移与 PD 分离场景里，图像块只是更大的普通块，按块数估迁移字节会系统性低估。最后，敏感图像的块共享范围要收敛到单租户，租户隔离优先于命中率。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>视觉 token 的 KV 单体比文本大一两个量级，图文容量按图数而非请求数估算。</li><li>嵌入缓存与 KV 块缓存是两级：键不同、短路成本不同，失效必须逐层传播。</li><li>驱逐按「字节 × 命中率」排序，大块先审；历史图可走降采样重算的第三条路。</li><li>模板、位置、编码版本全部进键，少一项即出现部分请求的能力退化。</li><li>KV 量化按模态分桶评测；音频 KV 默认短 TTL；租户隔离优先于命中率。</li><li>出处：据 PagedAttention（Kwon et al., SOSP 2023）、vLLM 多模态前缀缓存实现与 KV 管理课程口径整理。</li></ul>',6))])}const u=o(p,[["render",d]]);export{k as __pageData,u as default};
